# ─── Top-spacing nuclear fix via parent-document iframe ──────────────────────
# st.markdown scripts share the Streamlit React document but can lose the race
# against React's inline-style hydration. components.html iframes are same-origin
# on Streamlit Cloud, so window.parent.document gives reliable parent access.
_st_components.html("""
<script>
(function(){
  var doc = window.parent.document;
  if(!doc) return;
  // (0) Pre-inject custom favicon before React sets its own — eliminates pop-in flash
  (function(){
    var FAVICON = '/app/static/favicon.png';
    // Remove any existing icon links Streamlit may have injected
    doc.querySelectorAll('link[rel~="icon"],link[rel~="shortcut"]').forEach(function(l){ l.remove(); });
    var lnk = doc.createElement('link');
    lnk.rel = 'icon'; lnk.type = 'image/png'; lnk.href = FAVICON;
    doc.head.appendChild(lnk);
    // Watch for Streamlit re-injecting its own favicon and override immediately
    if(window.MutationObserver){
      new MutationObserver(function(muts){
        muts.forEach(function(m){
          m.addedNodes.forEach(function(n){
            if(n.nodeName === 'LINK' && /icon|shortcut/i.test(n.rel||'') &&
               !/favicon\.png/i.test(n.href||'')){
              n.href = FAVICON;
            }
          });
        });
      }).observe(doc.head,{childList:true});
    }
  })();
  // (a) Inject a <style> into parent <head> — loads after emotion CSS, wins cascade
  if(!doc.getElementById('dp-spacing-fix')){
    var s = doc.createElement('style');
    s.id = 'dp-spacing-fix';
    s.textContent =
      '[data-testid="stHeader"]{display:none!important;height:0!important;' +
        'position:absolute!important;top:-9999px!important;overflow:hidden!important}' +
      'header{display:none!important;height:0!important}' +
      '[data-testid="stToolbar"]{display:none!important;height:0!important}' +
      '[data-testid="stStatusWidget"]{display:none!important;opacity:0!important;' +
        'pointer-events:none!important;visibility:hidden!important}' +
      '[data-testid="stMain"]{padding-top:0!important;margin-top:0!important}' +
      '[data-testid="stMainBlockContainer"]{padding-top:0!important;margin-top:0!important}' +
      'section[data-testid="stMain"]>div{padding-top:0!important;margin-top:0!important}' +
      '.block-container{padding-top:0!important;margin-top:0!important}' +
      '.hero-banner{margin-top:0!important}' +
      '[data-testid="stApp"],[data-testid="stAppViewContainer"],[data-testid="stBottom"],' +
      'body,.main,.stApp{background:#0B1E38!important}';
    doc.head.appendChild(s);
  }
  // (b) Force inline styles — beats React inline style overrides
  function applyFix(){
    ['[data-testid="stMain"]','[data-testid="stMainBlockContainer"]','.block-container',
     'section[data-testid="stMain"]>div'].forEach(function(sel){
      doc.querySelectorAll(sel).forEach(function(el){
        el.style.setProperty('padding-top','0px','important');
        el.style.setProperty('margin-top','0px','important');
      });
    });
    doc.querySelectorAll('[data-testid="stHeader"],header').forEach(function(el){
      el.style.setProperty('display','none','important');
      el.style.setProperty('height','0px','important');
      el.style.setProperty('position','absolute','important');
      el.style.setProperty('top','-9999px','important');
    });
    doc.querySelectorAll('.hero-banner').forEach(function(el){
      el.style.setProperty('margin-top','0px','important');
    });
    // Force dark background on app shell to hide any residual gap
    ['[data-testid="stApp"]','[data-testid="stAppViewContainer"]','body'].forEach(function(sel){
      doc.querySelectorAll(sel).forEach(function(el){
        el.style.setProperty('background','#0B1E38','important');
        el.style.setProperty('background-color','#0B1E38','important');
      });
    });
    // (e) Kill host-injected Streamlit badges (viewer "Hosted with Streamlit",
    //     Manage app, deploy). These use randomized class hashes that drift
    //     between releases, so match by stable testid + case-insensitive class
    //     fragment + any anchor that links to a streamlit domain.
    var _bsel = [
      '[data-testid="stStatusWidget"]',
      '[data-testid="stStatusWidget"] *',
      '[data-testid="manage-app-button"]',
      '[data-testid="stAppDeployButton"]', '[data-testid="stDeployButton"]',
      '[class*="viewerBadge" i]', '[class*="profileContainer" i]',
      '[class*="appCreator" i]', '[class*="deployButton" i]',
      '[class*="StatusWidget" i]', '[class*="runningIcon" i]',
      '[class*="stSpinner" i]', 'button[aria-label*="Running" i]',
      'button[aria-label*="Stop" i]'
    ];
    _bsel.forEach(function(s){
      try { doc.querySelectorAll(s).forEach(function(el){
        el.style.setProperty('display', 'none', 'important');
      }); } catch(e){}
    });
    try {
      doc.querySelectorAll('a[href]').forEach(function(a){
        if(/streamlit\.(io|app)|share\.streamlit/i.test(a.getAttribute('href') || '')){
          var n = a;
          for(var i = 0; i < 4 && n; i++){
            var p = window.parent.getComputedStyle(n).position;
            if(p === 'fixed' || p === 'absolute'){
              n.style.setProperty('display', 'none', 'important'); break;
            }
            n = n.parentElement;
          }
          a.style.setProperty('display', 'none', 'important');
        }
      });
    } catch(e){}
  }
  // (c) RAF loop for 6 s — catches every React hydration tick
  applyFix();
  var end = Date.now() + 6000;
  (function raf(){ applyFix(); if(Date.now()<end) requestAnimationFrame(raf); })();
  // (d) MutationObserver watchdog
  if(window.MutationObserver){
    new MutationObserver(applyFix).observe(doc.documentElement,{
      childList:true,subtree:true,attributes:true,attributeFilter:['style','class']
    });
  }
})();
</script>
""", height=0, scrolling=False)

# ─── Paths ────────────────────────────────────────────────────────────────────
ROOT    = Path(__file__).parent.parent                          # project root
DB_PATH = ROOT / "data" / "analytics.sqlite"


def _init_db(conn: sqlite3.Connection) -> None:
    """Create tables if this is a fresh (empty) database — e.g. on Streamlit Cloud."""
    conn.executescript("""
        CREATE TABLE IF NOT EXISTS fact_str_metrics (
            source        TEXT,
            grain         TEXT,
            property_name TEXT,
            market        TEXT,
            submarket     TEXT,
            as_of_date    TEXT,
            metric_name   TEXT,
            metric_value  REAL,
            unit          TEXT
        );

        CREATE TABLE IF NOT EXISTS kpi_daily_summary (
            as_of_date      TEXT PRIMARY KEY,
            occ_pct         REAL,
            adr             REAL,
            revpar          REAL,
            occ_pct_yoy_pp  REAL,
            adr_yoy_pct     REAL,
            revpar_yoy_pct  REAL,
            occ_yoy         REAL,
            adr_yoy         REAL,
            revpar_yoy      REAL,
            is_occ_80       INTEGER,
            is_occ_90       INTEGER,
            created_at      TEXT
        );

        CREATE TABLE IF NOT EXISTS kpi_compression_quarterly (
            quarter           TEXT PRIMARY KEY,
            days_above_80_occ INTEGER,
            days_above_90_occ INTEGER,
            created_at        TEXT
        );

        CREATE TABLE IF NOT EXISTS load_log (
            id            INTEGER PRIMARY KEY AUTOINCREMENT,
            source        TEXT,
            grain         TEXT,
            file_name     TEXT,
            rows_inserted INTEGER,
            run_at        TEXT
        );

        CREATE TABLE IF NOT EXISTS costar_market_snapshot (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            report_period TEXT, market TEXT, submarket TEXT,
            total_supply_rooms INTEGER, total_demand_rooms INTEGER,
            occupancy_pct REAL, adr_usd REAL, revpar_usd REAL, room_revenue_usd REAL,
            occ_yoy_pp REAL, adr_yoy_pct REAL, revpar_yoy_pct REAL,
            supply_yoy_pct REAL, demand_yoy_pct REAL,
            data_source TEXT, report_type TEXT, notes TEXT,
            loaded_at TEXT DEFAULT (datetime('now'))
        );

        CREATE TABLE IF NOT EXISTS costar_monthly_performance (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            as_of_date TEXT, market TEXT, submarket TEXT,
            supply_rooms INTEGER, demand_rooms INTEGER,
            occupancy_pct REAL, adr_usd REAL, revpar_usd REAL, room_revenue_usd REAL,
            occ_yoy_pp REAL, adr_yoy_pct REAL, revpar_yoy_pct REAL,
            loaded_at TEXT DEFAULT (datetime('now'))
        );

        CREATE TABLE IF NOT EXISTS costar_supply_pipeline (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            property_name TEXT, market TEXT, submarket TEXT, address TEXT, city TEXT,
            rooms INTEGER, chain_scale TEXT, status TEXT, projected_open_date TEXT,
            brand TEXT, developer TEXT, floors INTEGER, lat REAL, lon REAL, notes TEXT,
            loaded_at TEXT DEFAULT (datetime('now'))
        );

        CREATE TABLE IF NOT EXISTS costar_chain_scale_breakdown (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            year TEXT, market TEXT, chain_scale TEXT, num_properties INTEGER, supply_rooms INTEGER,
            occupancy_pct REAL, adr_usd REAL, revpar_usd REAL, room_revenue_usd REAL,
            occ_yoy_pp REAL, adr_yoy_pct REAL, revpar_yoy_pct REAL,
            market_share_revpar_pct REAL,
            loaded_at TEXT DEFAULT (datetime('now'))
        );

        CREATE TABLE IF NOT EXISTS costar_competitive_set (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            property_name TEXT, market TEXT, submarket TEXT, brand TEXT, chain_scale TEXT,
            rooms INTEGER, year TEXT,
            occupancy_pct REAL, adr_usd REAL, revpar_usd REAL,
            mpi REAL, ari REAL, rgi REAL, notes TEXT,
            loaded_at TEXT DEFAULT (datetime('now'))
        );

        CREATE TABLE IF NOT EXISTS visit_ca_travel_forecast (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            year INTEGER, total_visits_m REAL, domestic_visits_m REAL, intl_visits_m REAL,
            total_yoy_pct REAL, domestic_yoy_pct REAL, intl_yoy_pct REAL,
            total_spend_b REAL, spend_yoy_pct REAL, notes TEXT,
            loaded_at TEXT DEFAULT (datetime('now'))
        );

        CREATE TABLE IF NOT EXISTS visit_ca_lodging_forecast (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            region TEXT, year INTEGER, supply_daily REAL, demand_daily REAL,
            occupancy_pct REAL, adr_usd REAL, revpar_usd REAL,
            occ_yoy_pp REAL, adr_yoy_pct REAL, revpar_yoy_pct REAL,
            loaded_at TEXT DEFAULT (datetime('now'))
        );

        CREATE TABLE IF NOT EXISTS visit_ca_airport_traffic (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            airport TEXT, year INTEGER, month INTEGER,
            total_pax INTEGER, domestic_pax INTEGER, intl_pax INTEGER,
            total_yoy_pct REAL, domestic_yoy_pct REAL, intl_yoy_pct REAL,
            loaded_at TEXT DEFAULT (datetime('now'))
        );

        CREATE TABLE IF NOT EXISTS visit_ca_intl_arrivals (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            year INTEGER, month INTEGER, total_intl INTEGER, total_overseas INTEGER,
            priority_markets INTEGER, top_country TEXT, top_country_arrivals INTEGER,
            loaded_at TEXT DEFAULT (datetime('now'))
        );
    """)
    conn.commit()


@st.cache_resource
def get_connection() -> sqlite3.Connection:
    """Return a persistent SQLite connection.

    Creates the database file and schema automatically if it does not exist
    (e.g. on Streamlit Cloud where *.sqlite is excluded from git).
    Dashboard code never writes data — all writes go through ETL scripts.
    """
    DB_PATH.parent.mkdir(parents=True, exist_ok=True)
    conn = sqlite3.connect(str(DB_PATH), check_same_thread=False, timeout=10)
    conn.row_factory = sqlite3.Row
    _init_db(conn)
    return conn

# ─── Data loaders ────────────────────────────────────────────────────────────
# TTL guide: real-time KPIs = 300s, social/campaign = 1800s, historical = 3600s

def _sql(query: str, ttl_hint: str = "") -> pd.DataFrame:
    """Execute a SQL query against the read-only dashboard connection.
    Returns an empty DataFrame on any error; logs the reason for debugging.
    """
    try:
        return pd.read_sql_query(query, get_connection())
    except Exception as _e:
        _logger.debug("SQL loader error (%s): %s", ttl_hint or query[:60], _e)
        return pd.DataFrame()

@st.cache_data(ttl=300)
def load_str_daily() -> pd.DataFrame:
    """Pivot fact_str_metrics (source='STR', grain='daily') → one row per date."""
    conn = get_connection()
    df = pd.read_sql_query(
        "SELECT as_of_date, metric_name, metric_value "
        "FROM fact_str_metrics "
        "WHERE source='STR' AND grain='daily' "
        "ORDER BY as_of_date",
        conn,
    )
    if df.empty:
        return pd.DataFrame()
    wide = (
        df.pivot_table(index="as_of_date", columns="metric_name",
                       values="metric_value", aggfunc="sum")
        .reset_index()
    )
    wide.columns.name = None
    wide.columns = [c.lower().replace(" ", "_") for c in wide.columns]
    wide["as_of_date"] = pd.to_datetime(wide["as_of_date"])
    # fact_str_metrics stores occupancy as 'occ' in decimal (0.674 = 67.4%)
    if "occ" in wide.columns and "occupancy" not in wide.columns:
        wide = wide.rename(columns={"occ": "occupancy"})
    if "occupancy" in wide.columns:
        wide["occupancy"] = wide["occupancy"] * 100
    for col in ["supply", "demand", "revenue", "occupancy", "adr", "revpar"]:
        if col not in wide.columns:
            wide[col] = np.nan
    return wide.sort_values("as_of_date").reset_index(drop=True)


@st.cache_data(ttl=300)
def load_kpi_daily() -> pd.DataFrame:
    conn = get_connection()
    df = pd.read_sql_query("SELECT * FROM kpi_daily_summary ORDER BY as_of_date", conn)
    df["as_of_date"] = pd.to_datetime(df["as_of_date"])
    return df


@st.cache_data(ttl=300)
def load_compression() -> pd.DataFrame:
    conn = get_connection()
    return pd.read_sql_query(
        "SELECT * FROM kpi_compression_quarterly ORDER BY quarter", conn
    )


@st.cache_data(ttl=300)
def load_load_log() -> pd.DataFrame:
    conn = get_connection()
    return pd.read_sql_query("SELECT * FROM load_log ORDER BY run_at DESC", conn)


@st.cache_data(ttl=300)
def load_str_monthly() -> pd.DataFrame:
    """Pivot fact_str_metrics (source='STR', grain='monthly') → one row per month.

    Monthly STR exports do not include an occ column.
    Occupancy is derived as demand / supply * 100.
    """
    conn = get_connection()
    df = pd.read_sql_query(
        "SELECT as_of_date, metric_name, metric_value "
        "FROM fact_str_metrics "
        "WHERE source='STR' AND grain='monthly' "
        "ORDER BY as_of_date",
        conn,
    )
    if df.empty:
        return pd.DataFrame()
    wide = (
        df.pivot_table(
            index="as_of_date", columns="metric_name",
            values="metric_value", aggfunc="mean",
        )
        .reset_index()
    )
    wide.columns.name = None
    wide.columns = [c.lower().replace(" ", "_") for c in wide.columns]
    wide["as_of_date"] = pd.to_datetime(wide["as_of_date"])
    # Normalise 'occ' → 'occupancy' if the column exists (decimal → percent)
    if "occ" in wide.columns and "occupancy" not in wide.columns:
        wide = wide.rename(columns={"occ": "occupancy"})
    if "occupancy" in wide.columns and wide["occupancy"].max() <= 1.0:
        wide["occupancy"] = wide["occupancy"] * 100
    # Monthly STR exports carry supply + demand but no occ; derive it
    if "occupancy" not in wide.columns or wide["occupancy"].isna().all():
        if "supply" in wide.columns and "demand" in wide.columns:
            wide["occupancy"] = (
                (wide["demand"] / wide["supply"] * 100)
                .where(wide["supply"] > 0)
            )
    for col in ["supply", "demand", "revenue", "occupancy", "adr", "revpar"]:
        if col not in wide.columns:
            wide[col] = np.nan
    return wide.sort_values("as_of_date").reset_index(drop=True)


