# ─── UI helpers ───────────────────────────────────────────────────────────────

def kpi_card(label, value, delta, positive=True, neutral=False,
             icon: str = "", date_label: str = "", raw_value: float = 0.0,
             sparkline_values: list = None, tooltip: str = "",
             back_html: str = "") -> str:
    css      = "kpi-delta-neutral" if neutral else ("kpi-delta-pos" if positive else "kpi-delta-neg")
    if neutral:
        arrow = "— "
        trend_icon = ""
    elif positive:
        arrow = ""
        trend_icon = '<svg width="10" height="10" viewBox="0 0 10 10" fill="none"><path d="M2 7L5 3L8 7" stroke="#059669" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>'
    else:
        arrow = ""
        trend_icon = '<svg width="10" height="10" viewBox="0 0 10 10" fill="none"><path d="M2 3L5 7L8 3" stroke="#DC2626" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg>'
    date_html  = f'<div class="kpi-date">{date_label}</div>' if date_label else ""
    svg        = kpi_metric_svg(label, positive, raw_value, sparkline_values)
    spark_html = sparkline_svg(sparkline_values, positive) if sparkline_values else ""
    title_attr = f' title="{tooltip}"' if tooltip else ""

    # ── Comparison value (e.g. "66.3% / 76.4%") — split with distinct colors ──
    val_str = str(value)
    is_comparison = " / " in val_str
    if is_comparison:
        parts    = val_str.split(" / ", 1)
        lbl_up   = label.upper()
        vs_idx   = lbl_up.find(" VS. ")
        if vs_idx != -1:
            _la = label[:vs_idx].split(":")[-1].strip()
            _lb = label[vs_idx + 5:].strip()
        else:
            _la, _lb = "A", "B"
        front_value_html = (
            f'<div style="display:flex;align-items:flex-end;gap:10px;margin:4px 0 2px;">'
            f'<div>'
            f'<div style="font-size:8px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;'
            f'color:#0891B2;margin-bottom:2px;">{_la}</div>'
            f'<div class="kpi-value" style="color:#0891B2;line-height:1;">{parts[0]}</div>'
            f'</div>'
            f'<div style="font-size:18px;color:#334155;font-weight:300;padding-bottom:4px;">/</div>'
            f'<div>'
            f'<div style="font-size:8px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;'
            f'color:#64748B;margin-bottom:2px;">{_lb}</div>'
            f'<div class="kpi-value" style="color:#94A3B8;line-height:1;">{parts[1]}</div>'
            f'</div>'
            f'</div>'
        )
    else:
        front_value_html = f'<div class="kpi-value">{value}</div>'

    # ── Auto-generate back face if not supplied ──────────────────────────────
    if not back_html:
        _trend_word  = "up" if (positive and not neutral) else ("down" if (not positive and not neutral) else "stable")
        _trend_color = "#10B981" if positive and not neutral else ("#EF4444" if not positive and not neutral else "#94A3B8")
        back_html = (
            f'<div style="font-size:10px;font-weight:800;color:#0891B2;text-transform:uppercase;'
            f'letter-spacing:.08em;margin-bottom:10px;">{label}</div>'
            f'<div style="font-size:22px;font-weight:800;color:#0F172A;margin-bottom:6px;">{value}</div>'
            f'<div style="font-size:12px;color:{_trend_color};font-weight:700;margin-bottom:8px;">'
            f'{trend_icon} Trending {_trend_word}: {delta}</div>'
            + (f'<div style="font-size:11px;color:#64748B;">{date_label}</div>' if date_label else '')
            + (f'<div style="font-size:11px;color:#94A3B8;margin-top:6px;">{tooltip}</div>' if tooltip else '')
        )

    # ── Flip card wrapper ─────────────────────────────────────────────────────
    return (
        f'<div class="dp-flip-card" onclick="this.classList.toggle(\'is-flipped\')">'
        f'<div class="dp-flip-inner">'
        # Front face
        f'<div class="dp-flip-front kpi-card"{title_attr}>'
        f'<div class="kpi-header">'
        f'<div class="kpi-label">{label}</div>'
        f'<div class="kpi-icon-svg">{svg}</div>'
        f'</div>'
        f'{front_value_html}'
        f'<div class="{css}">{trend_icon}{arrow}{delta}</div>'
        f'{date_html}{spark_html}'
        f'<span class="dp-flip-hint">↩ flip for detail</span>'
        f'</div>'
        # Back face
        f'<div class="dp-flip-back kpi-card" style="display:flex;flex-direction:column;">'
        f'{back_html}'
        f'<span class="dp-flip-hint">↩ flip back</span>'
        f'</div>'
        f'</div>'   # dp-flip-inner
        f'</div>'   # dp-flip-card
    )


def insight_card(title, body, kind="info", icon: str = "", date_label: str = "") -> str:
    svg_icon  = insight_icon_svg(kind, icon) if icon else ""
    icon_html = f'<span class="insight-icon">{svg_icon}</span>' if svg_icon else ""
    _kind_meta = {
        "positive": ("OPPORTUNITY", "#10B981"),
        "negative": ("RISK",        "#F04E37"),
        "warning":  ("WATCH",       "#F59E0B"),
        "info":     ("SIGNAL",      "#00C3BE"),
    }
    _lbl, _clr = _kind_meta.get(kind, ("INSIGHT", "#8FA3B8"))
    date_html = (
        f'<div style="font-size:10px;color:var(--dp-text-4);margin-top:8px;padding-top:6px;'
        f'border-top:1px solid var(--dp-border);">{date_label}</div>'
        if date_label else ""
    )
    _badge = (
        f'<span style="font-size:9px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;'
        f'color:{_clr};padding:2px 6px;border-radius:4px;background:rgba(0,0,0,0.06);'
        f'border:1px solid {_clr}44;">{_lbl}</span>'
    )
    return (
        # ── Flip card wrapper ──────────────────────────────────────────────
        f'<div class="dp-flip-card" onclick="this.classList.toggle(\'is-flipped\')">'
        f'<div class="dp-flip-inner">'
        # Front face — badge + title + flip hint
        f'<div class="dp-flip-front insight-card insight-{kind}" '
        f'style="display:flex;flex-direction:column;">'
        f'<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">'
        f'{_badge}</div>'
        f'<div class="insight-title">{icon_html}{md_to_html(title)}</div>'
        f'<span class="dp-flip-hint">↩ flip for details</span>'
        f'</div>'
        # Back face — full body + date
        f'<div class="dp-flip-back insight-card insight-{kind}" '
        f'style="display:flex;flex-direction:column;">'
        f'<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">'
        f'{_badge}</div>'
        f'<p class="insight-body" style="padding-left:0;flex:1;">{bold_key_data(md_to_html(body))}</p>'
        f'{date_html}'
        f'<span class="dp-flip-hint">↩ flip back</span>'
        f'</div>'
        f'</div>'  # dp-flip-inner
        f'</div>'  # dp-flip-card
    )


def event_stat(val, label, icon: str = "", date: str = "") -> str:
    svg       = event_icon_svg(icon) if icon else ""
    icon_html = f'<div class="event-icon">{svg}</div>' if svg else ""
    date_html = f'<div class="event-date">📅 {date}</div>' if date else ""
    return (
        f'<div class="event-stat">'
        f'{icon_html}'
        f'<div class="event-val">{val}</div>'
        f'<div class="event-label">{label}</div>'
        f'{date_html}'
        f'</div>'
    )


# ─── Wave 3 Chart Functions ───────────────────────────────────────────────────

def render_occ_heatmap(df_kpi):
    """12-month occupancy heatmap calendar."""
    if df_kpi.empty:
        return
    df = df_kpi.copy()
    df['as_of_date'] = pd.to_datetime(df['as_of_date'])
    df = df[df['as_of_date'] >= (pd.Timestamp.now() - pd.DateOffset(months=12))]
    if df.empty:
        return
    df['week'] = df['as_of_date'].dt.isocalendar().week.astype(int)
    df['dow'] = df['as_of_date'].dt.dayofweek  # 0=Mon
    df['month_label'] = df['as_of_date'].dt.strftime('%b %Y')

    fig = go.Figure(go.Heatmap(
        x=df['as_of_date'].dt.strftime('%Y-%m-%d'),
        y=df['as_of_date'].dt.strftime('%a'),
        z=df['occ_pct'],
        colorscale=[[0, '#e8f4fd'], [0.5, '#2196F3'], [0.8, '#FF9800'], [1.0, '#F44336']],
        zmin=40, zmax=100,
        colorbar=dict(title='Occ %', thickness=12),
        hovertemplate='%{x}<br>Occ: %{z:.1f}%<extra></extra>'
    ))
    fig.update_layout(
        title='Rolling 12-Month Occupancy Calendar',
        height=200,
        margin=dict(l=40, r=20, t=40, b=20),
        xaxis=dict(showgrid=False, tickangle=-45, tickfont=dict(size=9)),
        yaxis=dict(showgrid=False, categoryorder='array', categoryarray=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'])
    )
    st.plotly_chart(fig, use_container_width=True)


def render_comp_set_radar(df_str):
    """Dana Point vs comp set radar chart across 6 metrics."""
    import plotly.express as px
    try:
        with sqlite3.connect(DB_PATH + "?mode=ro", uri=True, timeout=10) as conn:
            df_group = pd.read_sql_query("""
                SELECT market, metric_name, AVG(metric_value) as avg_val
                FROM fact_str_metrics
                WHERE grain='daily' AND as_of_date >= date('now','-90 days')
                  AND metric_name IN ('occ','adr','revpar')
                GROUP BY market, metric_name
            """, conn)
    except Exception:
        return

    if df_group.empty:
        return

    pivot = df_group.pivot_table(index='market', columns='metric_name', values='avg_val').reset_index()
    if 'occ' in pivot.columns:
        pivot['occ'] = pivot['occ'] * 100  # decimal → pct

    markets = pivot['market'].tolist()
    categories = ['Occupancy %', 'ADR ($)', 'RevPAR ($)']

    fig = go.Figure()
    colors = ['#1a3a5c','#2196F3','#FF9800','#4CAF50','#9C27B0','#F44336']
    for i, row in pivot.iterrows():
        vals = []
        for col in ['occ','adr','revpar']:
            if col in pivot.columns and pd.notna(row.get(col)):
                col_max = pivot[col].max()
                vals.append((row[col] / col_max * 100) if col_max > 0 else 0)
            else:
                vals.append(0)
        vals_closed = vals + [vals[0]]
        cats_closed = categories + [categories[0]]
        fig.add_trace(go.Scatterpolar(
            r=vals_closed, theta=cats_closed,
            fill='toself', name=row['market'],
            line=dict(color=colors[i % len(colors)]),
            opacity=0.7
        ))

    fig.update_layout(
        polar=dict(radialaxis=dict(visible=True, range=[0, 110])),
        title='Comp Set Performance Index (90-Day Avg, Normalized)',
        height=420,
        legend=dict(font=dict(size=10))
    )
    st.plotly_chart(fig, use_container_width=True)
    st.caption("Values normalized to 100 = best performer in set. Source: STR.")


def render_adr_gas_scatter(df_kpi, df_gas):
    """ADR vs SoCal gas price correlation scatter."""
    import plotly.express as px
    if df_kpi.empty or df_gas.empty:
        st.info("Gas price data not yet available.")
        return

    df_kpi = df_kpi.copy()
    df_kpi['as_of_date'] = pd.to_datetime(df_kpi['as_of_date'])
    df_kpi['month'] = df_kpi['as_of_date'].dt.to_period('M').astype(str)
    monthly_adr = df_kpi.groupby('month')['adr'].mean().reset_index()

    df_gas = df_gas.copy()
    df_gas['month'] = pd.to_datetime(df_gas['period']).dt.to_period('M').astype(str)
    monthly_gas = df_gas.groupby('month')['price_per_gallon'].mean().reset_index()

    merged = monthly_adr.merge(monthly_gas, on='month')
    if merged.empty:
        return

    fig = px.scatter(merged, x='price_per_gallon', y='adr',
        trendline='ols', text='month',
        labels={'price_per_gallon': 'SoCal Gas Price ($/gal)', 'adr': 'Dana Point ADR ($)'},
        title='ADR vs. SoCal Gas Price Correlation',
        color_discrete_sequence=['#1a3a5c'])
    fig.update_traces(textposition='top center', textfont_size=8)
    fig.update_layout(height=380)
    st.plotly_chart(fig, use_container_width=True)

    corr = merged['adr'].corr(merged['price_per_gallon'])
    direction = "positive" if corr > 0 else "negative"
    st.caption(f"Correlation: {corr:.2f} ({direction}). {'Higher gas prices correlate with lower ADR, consistent with drive-market sensitivity.' if corr < -0.3 else 'Weak correlation suggests other demand drivers dominate over gas prices.'}")


def render_dma_bubble_map(df_dma):
    """US map with DMA bubbles sized by visitor days, colored by spend efficiency."""
    import plotly.express as px
    if df_dma.empty:
        return

    dma_coords = {
        'Los Angeles': (34.05, -118.25),
        'San Diego': (32.72, -117.16),
        'San Francisco': (37.77, -122.42),
        'Phoenix': (33.45, -112.07),
        'Las Vegas': (36.17, -115.14),
        'Salt Lake City': (40.76, -111.89),
        'Denver': (39.74, -104.98),
        'Dallas': (32.78, -96.80),
        'Chicago': (41.88, -87.63),
        'New York': (40.71, -74.01),
        'Seattle': (47.61, -122.33),
        'Portland': (45.52, -122.68),
        'Boston': (42.36, -71.06),
        'Washington DC': (38.91, -77.04),
        'Atlanta': (33.75, -84.39),
    }

    df = df_dma.copy()
    df['lat'] = df['dma'].map(lambda d: next((v[0] for k,v in dma_coords.items() if k.lower() in d.lower()), None))
    df['lon'] = df['dma'].map(lambda d: next((v[1] for k,v in dma_coords.items() if k.lower() in d.lower()), None))
    df = df.dropna(subset=['lat','lon'])

    if df.empty:
        st.info("DMA coordinate mapping not available for current markets.")
        return

    size_col = 'visitor_days_share_pct' if 'visitor_days_share_pct' in df.columns else df.select_dtypes('number').columns[0]
    color_col = 'avg_spend_usd' if 'avg_spend_usd' in df.columns else size_col

    fig = px.scatter_geo(df, lat='lat', lon='lon',
        size=size_col, color=color_col,
        hover_name='dma',
        hover_data={size_col: ':.1f', color_col: ':,.0f'},
        color_continuous_scale='Blues',
        size_max=40,
        scope='usa',
        title='Visitor Origin Markets — Bubble Size: Visitor Days Share, Color: Avg Spend/Trip')
    fig.update_layout(height=420, geo=dict(showland=True, landcolor='#f0f0f0', showlakes=False))
    st.plotly_chart(fig, use_container_width=True)


def render_feeder_sankey(df_dma, df_spending):
    """Sankey: Origin DMA → Transport Mode → Spend Category."""
    if df_dma.empty:
        return

    top_dmas = df_dma.nlargest(5, 'visitor_days_share_pct')['dma'].tolist() if 'visitor_days_share_pct' in df_dma.columns else df_dma['dma'].head(5).tolist()
    transport_modes = ['Drive Market', 'Fly Market']
    spend_cats = ['Accommodation', 'Dining', 'Retail']

    all_nodes = top_dmas + transport_modes + spend_cats
    node_idx = {n: i for i, n in enumerate(all_nodes)}

    sources, targets, values, labels_list = [], [], [], all_nodes

    drive_dmas = {'Los Angeles', 'San Diego', 'San Francisco', 'Las Vegas', 'Phoenix'}
    for dma in top_dmas:
        share = df_dma[df_dma['dma']==dma]['visitor_days_share_pct'].values[0] if 'visitor_days_share_pct' in df_dma.columns else 10
        is_drive = any(d.lower() in dma.lower() for d in drive_dmas)
        sources.append(node_idx[dma]); targets.append(node_idx['Drive Market' if is_drive else 'Fly Market']); values.append(float(share))

    drive_total = sum(float(df_dma[df_dma['dma']==d]['visitor_days_share_pct'].values[0]) for d in top_dmas if any(x.lower() in d.lower() for x in drive_dmas) and 'visitor_days_share_pct' in df_dma.columns and len(df_dma[df_dma['dma']==d]) > 0)
    fly_total = sum(float(df_dma[df_dma['dma']==d]['visitor_days_share_pct'].values[0]) for d in top_dmas if not any(x.lower() in d.lower() for x in drive_dmas) and 'visitor_days_share_pct' in df_dma.columns and len(df_dma[df_dma['dma']==d]) > 0)
    for mode, total in [('Drive Market', drive_total), ('Fly Market', fly_total)]:
        for cat, pct in [('Accommodation', 0.35), ('Dining', 0.30), ('Retail', 0.35)]:
            sources.append(node_idx[mode]); targets.append(node_idx[cat]); values.append(total * pct)

    fig = go.Figure(go.Sankey(
        node=dict(label=labels_list, pad=15, thickness=20,
                  color=['#1a3a5c']*len(top_dmas) + ['#2196F3','#FF9800'] + ['#4CAF50','#E91E63','#9C27B0']),
        link=dict(source=sources, target=targets, value=values, color='rgba(33,150,243,0.3)')
    ))
    fig.update_layout(title='Visitor Journey: Origin Market → Transport Mode → Spend Category', height=380)
    st.plotly_chart(fig, use_container_width=True)
    st.caption("Spend splits estimated from Datafy category data. Drive vs. fly classification based on distance from Dana Point.")


def render_booking_pace(df_kpi):
    """Rolling 90-day occupancy vs same-period-last-year."""
    if df_kpi.empty:
        return

    df = df_kpi.copy()
    df['as_of_date'] = pd.to_datetime(df['as_of_date'])
    df = df.sort_values('as_of_date')

    end = df['as_of_date'].max()
    start = end - pd.Timedelta(days=90)
    current = df[(df['as_of_date'] >= start) & (df['as_of_date'] <= end)][['as_of_date','occ_pct','adr','revpar']].copy()

    prior = df[(df['as_of_date'] >= start - pd.DateOffset(years=1)) &
               (df['as_of_date'] <= end - pd.DateOffset(years=1))][['as_of_date','occ_pct']].copy()
    prior['as_of_date'] = prior['as_of_date'] + pd.DateOffset(years=1)
    prior = prior.rename(columns={'occ_pct': 'occ_pct_prior'})

    merged = current.merge(prior, on='as_of_date', how='left')

    fig = go.Figure()
    fig.add_trace(go.Scatter(x=merged['as_of_date'], y=merged['occ_pct'],
        name='Current Year', line=dict(color='#1a3a5c', width=2.5)))
    if 'occ_pct_prior' in merged.columns and merged['occ_pct_prior'].notna().any():
        fig.add_trace(go.Scatter(x=merged['as_of_date'], y=merged['occ_pct_prior'],
            name='Prior Year', line=dict(color='#90CAF9', width=1.5, dash='dash')))

    fig.add_hline(y=80, line_dash='dot', line_color='#FF9800',
        annotation_text='80% Compression', annotation_position='right')

    fig.update_layout(
        title='Rolling 90-Day Occupancy Pace vs. Prior Year',
        xaxis_title='Date', yaxis_title='Occupancy %',
        yaxis=dict(range=[30, 105]),
        height=360, legend=dict(orientation='h', y=1.02)
    )
    st.plotly_chart(fig, use_container_width=True)


def render_content_funnel():
    """Social engagement → sessions → attributed trips funnel."""
    try:
        with sqlite3.connect(DB_PATH + "?mode=ro", uri=True, timeout=10) as conn:
            eng_df = pd.read_sql_query("""
                SELECT COALESCE(SUM(likes + comments), 0) as total_eng
                FROM later_ig_posts
                WHERE date >= date('now','-30 days')
            """, conn)
            engagements = int(eng_df['total_eng'].iloc[0]) if not eng_df.empty else 0

            sess_df = pd.read_sql_query("""
                SELECT COALESCE(SUM(sessions), 0) as total_sessions
                FROM datafy_social_traffic_sources
                WHERE channel LIKE '%social%' OR channel LIKE '%Social%'
            """, conn)
            sessions = int(sess_df['total_sessions'].iloc[0]) if not sess_df.empty else 0

            trips_df = pd.read_sql_query("""
                SELECT COALESCE(SUM(attributable_trips), 0) as total_trips
                FROM datafy_attribution_website_kpis
            """, conn)
            trips = int(trips_df['total_trips'].iloc[0]) if not trips_df.empty else 0
    except Exception:
        return

    if engagements == 0 and sessions == 0 and trips == 0:
        return

    fig = go.Figure(go.Funnel(
        y=['Social Engagements', 'Website Sessions', 'Attributed Trips'],
        x=[max(engagements, 1), max(sessions, 1), max(trips, 1)],
        textinfo='value+percent initial',
        marker=dict(color=['#1a3a5c', '#2196F3', '#4CAF50'])
    ))
    fig.update_layout(title='Content-to-Visit Attribution Funnel (30-Day)', height=320)
    st.plotly_chart(fig, use_container_width=True)


# ─── End Wave 3 Chart Functions ───────────────────────────────────────────────

def style_fig(fig: go.Figure, height: int = 360) -> go.Figure:
    """Deep Ocean dark chart theme — Dana Point PULSE v9.
    Full dark mode: transparent bg, vibrant ocean-teal palette, premium grid.
    """
    _font  = "Syne, DM Sans, Inter, system-ui, sans-serif"
    _title = "Syne, Outfit, DM Sans, system-ui, sans-serif"
    _colorway = [
        "#0891B2",  # Pacific teal (primary)
        "#F5B940",  # coastal gold
        "#10B981",  # wave green
        "#A78BFA",  # purple
        "#FB923C",  # sunset orange
        "#EF4444",  # coral red
        "#38BDF8",  # sky blue
        "#6EE7B7",  # seafoam
    ]
    fig.update_layout(
        plot_bgcolor  = "rgba(0,0,0,0)",
        paper_bgcolor = "rgba(0,0,0,0)",
        font    = dict(family=_font, size=12.5, color="#334155"),
        height  = height,
        autosize = True,
        margin  = dict(l=14, r=20, t=64, b=36, autoexpand=True),
        transition = {"duration": 500, "easing": "cubic-in-out"},
        legend = dict(
            orientation = "h",
            yanchor = "bottom", y = 1.02,
            xanchor = "left",   x = 0,
            font    = dict(size=11, family=_font, color="#64748B"),
            bgcolor = "rgba(255,255,255,0.80)",
            bordercolor = "rgba(100,116,139,0.20)",
            borderwidth = 1,
            itemsizing  = "constant",
            tracegroupgap = 4,
        ),
        uniformtext = dict(minsize=9, mode="hide"),
        hoverlabel = dict(
            bgcolor     = "rgba(20,50,80,0.96)",
            bordercolor = "rgba(0,212,200,0.60)",
            font        = dict(size=13, family=_font, color="#EFF6FF"),
            namelength  = -1,
            align       = "left",
        ),
        colorway = _colorway,
        modebar = dict(
            bgcolor     = "rgba(0,0,0,0)",
            color       = "#5A7A95",
            activecolor = "#0891B2",
        ),
        dragmode = "zoom",
    )
    fig.update_xaxes(
        showgrid    = False,
        zeroline    = False,
        tickfont    = dict(size=12, family=_font, color="#94A3B8"),
        linecolor   = "rgba(255,255,255,0.10)",
        linewidth   = 1,
        showline    = True,
        ticks       = "outside",
        ticklen     = 3,
        tickcolor   = "rgba(255,255,255,0.08)",
        automargin  = True,
        tickangle   = -30,
    )
    fig.update_yaxes(
        gridcolor   = "rgba(255,255,255,0.04)",   # Linear-standard ultra-thin
        gridwidth   = 1,
        griddash    = "dot",
        zeroline    = False,
        tickfont    = dict(size=12, family="'JetBrains Mono', " + _font, color="#94A3B8"),
        showline    = False,
        ticks       = "",
        automargin  = True,
    )
    # ── Vibrant fill palette with stronger gradients ──────────────────────
    _fill_palette = [
        "rgba(0,212,200,0.16)",   "rgba(245,185,64,0.14)",
        "rgba(16,185,129,0.14)",  "rgba(167,139,250,0.13)",
        "rgba(251,146,60,0.14)",  "rgba(56,189,248,0.14)",
    ]
    _line_palette = [
        "#0891B2", "#F5B940", "#10B981", "#A78BFA", "#FB923C", "#38BDF8",
    ]
    _fill_idx = 0
    for trace in fig.data:
        ttype = type(trace).__name__
        if ttype in ("Scatter", "Scattergl"):
            mode = str(getattr(trace, "mode", "") or "")
            if "lines" in mode and getattr(trace, "fill", None) in (None, "none"):
                trace.fill = "tozeroy"
                _c = (getattr(trace.line, "color", None) or _colorway[0])
                if "rgb(" in str(_c):
                    # Convert existing rgb to rgba with stronger opacity
                    trace.fillcolor = _c.replace("rgb(", "rgba(").replace(")", ",0.13)")
                else:
                    trace.fillcolor = _fill_palette[_fill_idx % len(_fill_palette)]
                    # Ensure line color matches fill color
                    if not getattr(trace.line, "color", None):
                        try: trace.line.color = _line_palette[_fill_idx % len(_line_palette)]
                        except Exception: pass
                    _fill_idx += 1
            # Smooth spline for organic painted feel
            if hasattr(trace, "line") and trace.line is not None:
                if not getattr(trace.line, "shape", None):
                    try:
                        trace.line.shape = "spline"
                        trace.line.smoothing = 0.8
                    except Exception:
                        pass
                try:
                    if (getattr(trace.line, "width", None) is None or
                            getattr(trace.line, "width", 2) < 2):
                        trace.line.width = 2.5
                except Exception:
                    pass
        elif ttype == "Bar":
            try:
                if not getattr(trace.marker, "cornerradius", None):
                    trace.marker.cornerradius = 5
            except Exception:
                pass
            # Add subtle opacity variation for bar depth
            try:
                if getattr(trace.marker, "opacity", None) is None:
                    trace.marker.opacity = 0.88
            except Exception:
                pass
    # ── Title styling (white text on dark bg) ─────────────────────────────
    if fig.layout.title and fig.layout.title.text:
        fig.update_layout(
            title_font = dict(family=_title, size=14, color="#334155"),
            title_x    = 0,
            title_pad  = dict(l=4, t=4),
        )
    return fig


def sec_div(title: str) -> str:
    """Returns HTML for a section divider with centered pill label."""
    return (
        f'<div class="section-divider">'
        f'<div class="section-divider-line"></div>'
        f'<div class="section-divider-title">{title}</div>'
        f'<div class="section-divider-line-r"></div>'
        f'</div>'
    )


# ── Section HTML report generator ─────────────────────────────────────────────
def generate_section_html(label: str, df: "pd.DataFrame", subtitle: str = "") -> str:
    """Generate a print-ready HTML report for any section — same styling as Board Report.
    Download → open in browser → File › Print › Save as PDF."""
    _date_str  = datetime.now().strftime("%B %d, %Y")
    _period    = datetime.now().strftime("%B %Y")
    _sub_str   = f" — {subtitle}" if subtitle else f" — {_period}"

    # Build table (cap at 200 rows, 25 cols to keep HTML small)
    if not df.empty:
        _cols  = [c for c in df.columns if not c.startswith("_")][:25]
        _thead = "".join(f"<th>{c.replace('_',' ').title()}</th>" for c in _cols)
        _tbody = ""
        for _, row in df.head(200).iterrows():
            _cells = "".join(f"<td>{'' if pd.isna(row[c]) else row[c]}</td>" for c in _cols)
            _tbody += f"<tr>{_cells}</tr>"
        _table_html = (
            f'<table><thead><tr>{_thead}</tr></thead>'
            f'<tbody>{_tbody}</tbody></table>'
        )
    else:
        _table_html = "<p style='color:#5A7A95;font-style:italic;'>No data available.</p>"

    return f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>{label} — Dana Point PULSE</title>
  <style>
    @page {{ margin: 0.75in; }}
    * {{ box-sizing: border-box; margin: 0; padding: 0; }}
    body {{ font-family: Arial, Helvetica, sans-serif; font-size: 11px; color: #1a2b3c; background: #fff; }}
    .hdr {{ background: #0F1C2E; color: #fff; padding: 18px 24px 14px; }}
    .hdr-brand {{ font-size: 13px; font-weight: 700; color: #0891B2; letter-spacing: .04em; text-transform: uppercase; }}
    .hdr-title {{ font-size: 20px; font-weight: 700; color: #fff; margin: 4px 0 2px; }}
    .hdr-meta  {{ font-size: 10px; color: #5A7A95; }}
    .body {{ padding: 20px 24px; }}
    h2 {{ font-size: 13px; font-weight: 700; color: #0F1C2E; border-bottom: 2px solid #0891B2;
          padding-bottom: 5px; margin: 0 0 12px; }}
    table {{ width: 100%; border-collapse: collapse; font-size: 10px; margin-bottom: 12px; }}
    th {{ background: #0F1C2E; color: #0891B2; padding: 5px 8px; text-align: left;
          font-weight: 700; font-size: 9px; text-transform: uppercase; letter-spacing: .06em; }}
    td {{ padding: 5px 8px; border-bottom: 1px solid #e8eef3; vertical-align: top; }}
    tr:nth-child(even) td {{ background: #f5f8fa; }}
    .footer {{ margin-top: 24px; padding-top: 10px; border-top: 1px solid #e0e8ef;
               font-size: 9px; color: #8AABB8; line-height: 1.5; }}
    @media print {{
      body {{ -webkit-print-color-adjust: exact; print-color-adjust: exact; }}
    }}
  </style>
</head>
<body>
  <div class="hdr">
    <div class="hdr-brand">Dana Point PULSE · GloCon Solutions LLC</div>
    <div class="hdr-title">{label}{_sub_str}</div>
    <div class="hdr-meta">Generated {_date_str} · Data Sources: STR · Datafy · CoStar · Visit California</div>
  </div>
  <div class="body">
    <h2>{label}</h2>
    {_table_html}
    <div class="footer">
      Dana Point PULSE is a proprietary analytics platform developed by GloCon Solutions LLC for Visit Dana Point.<br>
      Data sources: STR (hotel performance) · Datafy (visitor economy) · CoStar (market supply/pipeline) · Visit California · Later.com (social).<br>
      Live dashboard: https://vdp-analytics.streamlit.app · Contact: john@gloconsolutions.com
    </div>
  </div>
</body>
</html>"""


# ── Universal Share Bar ────────────────────────────────────────────────────────
# PDF (print-ready HTML) · JPEG (screenshot) · CSV · Email (mailto) · Link (copy URL)
# Usage: render_share_bar("Hotel Trends", df=df_daily, file_name="hotel_trends", key="tr")
def render_share_bar(
    label: str,
    df: "pd.DataFrame | None" = None,
    file_name: str = "pulse_data",
    key: str = "share",
    subtitle: str = "",
) -> None:
    """PDF · JPEG · CSV · Email · Link — same pattern as Board Report, for every section."""
    _has_df   = df is not None and not df.empty
    _date_sfx = datetime.now().strftime("%Y%m%d")
    _subj = f"Dana%20Point%20PULSE%20%E2%80%94%20{label.replace(' ', '%20')}"
    _body = (
        f"Hi%2C%0A%0APlease%20find%20the%20{label.replace(' ', '%20')}%20"
        f"section%20from%20the%20Dana%20Point%20PULSE%20dashboard.%0A%0A"
        f"View%20live%20dashboard%3A%20https%3A%2F%2Fvdp-analytics.streamlit.app%0A%0A"
        f"Best%2C%0AJohn%20Picou%20%7C%20GloCon%20Solutions%20LLC"
    )
    _btn_style = (
        "width:100%;height:32px;background:rgba(255,255,255,0.07);"
        "border:1px solid rgba(255,255,255,0.18);border-radius:8px;"
        "cursor:pointer;color:#334155;font-size:11px;font-weight:600;"
        "font-family:Inter,sans-serif;transition:background 0.2s;"
    )
    _hover_on  = "this.style.background='rgba(0,212,200,0.15)'"
    _hover_off = "this.style.background='rgba(255,255,255,0.07)'"

    # Column layout — include PDF + CSV only when df available
    if _has_df:
        _cols = st.columns([1, 1, 1, 1, 1, 3])
        _ci   = 0
    else:
        _cols = st.columns([1, 1, 1, 3])
        _ci   = 0

    # ── 📄 PDF (print-ready HTML) ─────────────────────────────────────────────
    if _has_df:
        with _cols[_ci]:
            _html_rpt = generate_section_html(label, df, subtitle)
            st.download_button(
                "📄 PDF",
                _html_rpt.encode("utf-8"),
                file_name=f"{file_name}_{_date_sfx}.html",
                mime="text/html",
                key=f"pdf_sb_{key}",
                use_container_width=True,
                help="Download print-ready report → open in browser → File › Print › Save as PDF. Optimized for A4/Letter.",
            )
        _ci += 1

    # ── 📸 JPEG (html2canvas screenshot) ─────────────────────────────────────
    _jpg_name = f"{file_name}_{_date_sfx}.jpg"
    with _cols[_ci]:
        _st_components.html(
            f'<script src="https://html2canvas.hertzen.com/dist/html2canvas.min.js"></script>'
            f'<button id="jpegbtn_{key}" '
            f'onmouseover="{_hover_on}" onmouseout="{_hover_off}" '
            f'onclick="var me=this;me.disabled=true;me.textContent=\'…\';\n'
            f'html2canvas('
            f'window.parent.document.querySelector(\'[data-testid=stMainBlockContainer]\')'
            f'||window.parent.document.body,'
            f'{{scale:2,useCORS:true,backgroundColor:\'#0F1C2E\'}})'
            f'.then(function(c){{'
            f'var a=document.createElement(\'a\');a.download=\'{_jpg_name}\';'
            f'a.href=c.toDataURL(\'image/jpeg\',0.92);a.click();'
            f'me.disabled=false;me.textContent=\'📸 JPEG\';}}'
            f').catch(function(){{me.disabled=false;me.textContent=\'📸 JPEG\';}});" '
            f'style="{_btn_style}">📸 JPEG</button>',
            height=38,
        )
    _ci += 1

    # ── ⬇️ CSV ────────────────────────────────────────────────────────────────
    if _has_df:
        with _cols[_ci]:
            st.download_button(
                "⬇️ CSV",
                df.to_csv(index=False).encode(),
                file_name=f"{file_name}_{_date_sfx}.csv",
                mime="text/csv",
                key=f"csv_sb_{key}",
                use_container_width=True,
                help=f"Download {label} data as CSV",
            )
        _ci += 1

    # ── 📧 Email ──────────────────────────────────────────────────────────────
    with _cols[_ci]:
        st.link_button(
            "📧 Email",
            f"mailto:?subject={_subj}&body={_body}",
            use_container_width=True,
            help="Share this section via email",
        )
    _ci += 1

    # ── 🔗 Link (copy dashboard URL to clipboard) ─────────────────────────────
    with _cols[_ci]:
        _st_components.html(
            f'<button id="lnkbtn_{key}" '
            f'onmouseover="{_hover_on}" onmouseout="{_hover_off}" '
            f'onclick="var me=this;\n'
            f'var u=window.parent.location.href;\n'
            f'if(navigator.clipboard){{navigator.clipboard.writeText(u)'
            f'.then(function(){{me.textContent=\'✓ Copied!\';'
            f'setTimeout(function(){{me.textContent=\'🔗 Link\';}},2000);}}'
            f').catch(function(){{window.parent.prompt(\'Copy link:\',u);}});}}\n'
            f'else{{window.parent.prompt(\'Copy link:\',u);}}" '
            f'style="{_btn_style}">🔗 Link</button>',
            height=38,
        )

    # Caption — PDF how-to (matches Board Report pattern)
    if _has_df:
        st.caption(
            "📄 Opens as a formatted HTML document. "
            "To save as PDF: open in browser → File → Print → 'Save as PDF'. "
            "Optimized for A4/Letter paper.   📧 Share via Email sends the dashboard link."
        )



def render_kpi_ticker(df_kpi: "pd.DataFrame", df_dfy: "pd.DataFrame",
                      df_later_ig: "pd.DataFrame") -> str:
    """Bloomberg/1ax-style dual-row KPI ticker with live data."""
    import math

    def _item(label: str, val: str, delta: str = "", positive: bool | None = None, is_status: bool = False, date_label: str = "") -> str:
        delta_cls = ""
        if delta and positive is True:   delta_cls = "pulse-ticker-pos"
        elif delta and positive is False: delta_cls = "pulse-ticker-neg"
        delta_html = f'<span class="{delta_cls}">{delta}</span>' if delta else ""
        status_cls = "pulse-ticker-status" if is_status else ""
        date_html = f'<span class="pulse-ticker-date">{date_label}</span>' if date_label else ""
        return (
            f'<div class="pulse-ticker-item {status_cls}">'
            f'<span class="pulse-ticker-label {status_cls}">{label}</span>'
            f'<span class="pulse-ticker-val {status_cls}">{val}</span>'
            f'{delta_html}{date_html}'
            f'</div>'
        )

    # ── Pull live metrics ──────────────────────────────────────────────────────
    occ_val   = adr_val = rvp_val = "—"
    occ_d     = adr_d   = rvp_d   = ""
    occ_pos   = adr_pos = rvp_pos = None
    if not df_kpi.empty:
        _rec = df_kpi.sort_values("as_of_date").iloc[-1]
        try:
            occ_val = f"{float(_rec.get('occ_pct', 0)):.1f}%"
            _od = float(_rec.get("occ_yoy", 0))
            occ_d = f"{'▲' if _od>=0 else '▼'}{abs(_od):.1f}pp"; occ_pos = _od >= 0
        except Exception: pass
        try:
            adr_val = f"${float(_rec.get('adr', 0)):,.0f}"
            _ad = float(_rec.get("adr_yoy", 0))
            adr_d = f"{'▲' if _ad>=0 else '▼'}{abs(_ad):.1f}%"; adr_pos = _ad >= 0
        except Exception: pass
        try:
            rvp_val = f"${float(_rec.get('revpar', 0)):,.0f}"
            _rd = float(_rec.get("revpar_yoy", 0))
            rvp_d = f"{'▲' if _rd>=0 else '▼'}{abs(_rd):.1f}%"; rvp_pos = _rd >= 0
        except Exception: pass

    trips_val = "—"; oos_val = "—"; roas_val = "—"; top_dma = "—"
    if not df_dfy.empty:
        try:
            _r = df_dfy.iloc[0]
            trips_val = f"{float(_r.get('total_trips',0))/1e6:.2f}M" if _r.get('total_trips') else "—"
            oos_val   = f"{float(_r.get('out_of_state_vd_pct',0)):.0f}%"
            roas_val  = f"{float(_r.get('media_roas',0)):.1f}×" if _r.get('media_roas') else "—"
            top_dma   = str(_r.get("top_dma","Los Angeles"))
        except Exception: pass

    ig_val = "—"
    _ig_date_label = ""
    if not df_later_ig.empty:
        try:
            _ig = df_later_ig.sort_values("date").iloc[-1]
            ig_val = f"{int(float(_ig.get('followers',0))):,}" if _ig.get('followers') else "—"
            _ig_date_label = str(_ig.get("date", ""))[:7]
        except Exception: pass

    # ── Extract STR date label ──────────────────────────────────────────────────
    _str_date_label = ""
    if not df_kpi.empty:
        try:
            _str_date_label = f"as of {str(_rec.get('as_of_date', ''))[:7]}"
        except Exception: pass

    # ── Build rows (skip items with no data) ────────────────────────────────────
    row1_items = []
    if occ_val != "—": row1_items.append(_item("⬤ LIVE", "DANA POINT PULSE", is_status=True))
    else: row1_items.append(_item("⬤ LIVE", "DANA POINT PULSE", is_status=True))  # Always show LIVE
    if occ_val != "—": row1_items.append(_item("OCCUPANCY", occ_val, occ_d, occ_pos, date_label=_str_date_label))
    if adr_val != "—": row1_items.append(_item("ADR", adr_val, adr_d, adr_pos, date_label=_str_date_label))
    if rvp_val != "—": row1_items.append(_item("REVPAR", rvp_val, rvp_d, rvp_pos, date_label=_str_date_label))
    if trips_val != "—": row1_items.append(_item("ANNUAL TRIPS", trips_val, date_label="2024 Annual"))
    if oos_val != "—": row1_items.append(_item("OUT-OF-STATE", oos_val, date_label="2024 Annual"))
    if roas_val != "—": row1_items.append(_item("MEDIA ROAS", roas_val, date_label="2024 Annual"))
    if top_dma != "—": row1_items.append(_item("TOP FEEDER DMA", top_dma, date_label="2024 Annual"))
    if ig_val != "—": row1_items.append(_item("IG FOLLOWING", ig_val, date_label=_ig_date_label))

    # Group KPIs for ticker
    _grp_tbid_str = "—"; _grp_uplift_str = "—"; _grp_risk_str = "—"
    try:
        import sqlite3 as _sq3
        _gconn = _sq3.connect(DB_PATH, timeout=5)
        _gconn.row_factory = _sq3.Row
        _grow = _gconn.execute(
            "SELECT estimated_group_tbid_rev_low, estimated_group_tbid_rev_high, "
            "tbid_uplift_per_5pp_shift, compression_days_annual "
            "FROM group_intelligence ORDER BY benchmark_date DESC LIMIT 1"
        ).fetchone()
        _gconn.close()
        if _grow:
            _tlow = float(_grow["estimated_group_tbid_rev_low"] or 0)
            _thigh = float(_grow["estimated_group_tbid_rev_high"] or 0)
            _uplft = float(_grow["tbid_uplift_per_5pp_shift"] or 0)
            _cdays = int(_grow["compression_days_annual"] or 0)
            _grp_tbid_str   = f"${_tlow/1e6:.1f}M–${_thigh/1e6:.1f}M"
            _grp_uplift_str = f"+${_uplft/1000:.0f}K/5pp"
            _grp_risk_str   = "HIGH" if _cdays >= 30 else ("MOD" if _cdays >= 10 else "LOW")
    except Exception:
        pass

    row2_items = [
        _item("TBID BLEND", "1.25%", date_label="City Ordinance"),
        _item("TOT RATE", "10%", date_label="City Ordinance"),
        _item("GROUP TBID EST", _grp_tbid_str, date_label="CoStar Est."),
        _item("GROUP MIX UPLIFT", _grp_uplift_str, date_label="CoStar Est."),
        _item("GROUP DISPLACE RISK", _grp_risk_str),
        _item("OHANA FEST ADR LIFT", "+$139"),
        _item("SPEND MULTIPLIER", "3.2×"),
        _item("OOS VISITORS", "68%"),
        _item("AVG LOS", "2.0 days"),
        _item("DAYTRIP CONVERSION OPP", "~$15M"),
        _item("PIPELINE ROOMS", "CoStar"),
        _item("DATA SOURCES", "STR · Datafy · CoStar"),
    ]
    # Duplicate for seamless loop
    row1_html = "".join(row1_items * 3)
    row2_html = "".join(row2_items * 3)

    return (
        f'<div class="pulse-ticker-wrap">'
        f'<div class="pulse-ticker-track left">{row1_html}</div>'
        f'<div class="pulse-ticker-track right" style="border-top:1px solid rgba(255,255,255,0.05);">{row2_html}</div>'
        f'</div>'
    )


def render_painted_occ_heatmap(df_kpi_daily: "pd.DataFrame") -> "go.Figure | None":
    """Giorgia Lupi / Long-Covid painted-density occupancy calendar.

    Instead of bars, renders a 7-column weekly calendar grid where each cell
    is a scatter bubble sized + colored by occupancy — density = intensity.
    Returns a Plotly figure, or None if insufficient data.
    """
    if df_kpi_daily is None or df_kpi_daily.empty:
        return None
    try:
        _df = df_kpi_daily.copy()
        _df["as_of_date"] = pd.to_datetime(_df["as_of_date"], errors="coerce")
        _df = _df.dropna(subset=["as_of_date", "occ_pct"]).copy()
        if len(_df) < 30:
            return None
        # Keep last 365 days
        _cutoff = _df["as_of_date"].max() - pd.Timedelta(days=365)
        _df = _df[_df["as_of_date"] >= _cutoff].copy()
        _df["week"]    = _df["as_of_date"].dt.isocalendar().week.astype(int)
        _df["dow"]     = _df["as_of_date"].dt.dayofweek   # 0=Mon … 6=Sun
        _df["year"]    = _df["as_of_date"].dt.year
        # Create week-index for X axis (unique per year-week)
        _df = _df.sort_values("as_of_date")
        _df["week_idx"] = (
            (_df["year"] - _df["year"].min()) * 53 + _df["week"]
        )
        _df["week_idx"] = _df["week_idx"] - _df["week_idx"].min()
        # Colour scale: pale → saturated teal at 80%, flame at 90%+
        # Map occ_pct to color intensity
        def _occ_color(v: float) -> str:
            v = max(0, min(100, v))
            if v >= 90:   return f"rgba(234,88,12,{min(0.92,0.55+v/200):.2f})"   # flame orange
            if v >= 80:   return f"rgba(5,103,200,{min(0.90,0.40+v/180):.2f})"   # deep teal
            if v >= 65:   return f"rgba(5,103,200,{0.18+v/280:.2f})"              # medium teal
            return f"rgba(5,103,200,{0.06+v/400:.2f})"                             # pale wash

        _df["color"] = _df["occ_pct"].apply(_occ_color)
        # Bubble size scales with occupancy — bigger = higher pressure
        _df["size"]  = _df["occ_pct"].clip(40,100).apply(lambda v: 6 + (v-40)/60*14)

        # Month label for x-axis ticks
        _df["month_label"] = _df["as_of_date"].dt.strftime("%b %Y")
        _dow_labels = ["Mon","Tue","Wed","Thu","Fri","Sat","Sun"]

        fig = go.Figure()
        fig.add_trace(go.Scatter(
            x=_df["week_idx"],
            y=_df["dow"],
            mode="markers",
            marker=dict(
                size=_df["size"],
                color=_df["color"],
                line=dict(width=0),
                symbol="circle",
            ),
            hovertemplate=(
                "<b>%{customdata[0]}</b><br>"
                "Occupancy: <b>%{customdata[1]:.1f}%</b><br>"
                "%{customdata[2]}"
                "<extra></extra>"
            ),
            customdata=list(zip(
                _df["as_of_date"].dt.strftime("%a %b %d, %Y"),
                _df["occ_pct"],
                _df["occ_pct"].apply(
                    lambda v: "🔥 COMPRESSION — rate premium justified"
                    if v >= 90 else ("🎯 High demand" if v >= 80 else "")
                ),
            )),
            showlegend=False,
        ))
        # Month boundary lines
        _month_starts = _df.groupby(_df["as_of_date"].dt.to_period("M"))["week_idx"].min()
        for _ms in _month_starts.values[1:]:
            fig.add_vline(x=_ms - 0.5, line_width=1,
                         line_color="rgba(15,28,46,0.12)", line_dash="dot")
        # Month labels
        _tick_vals = _month_starts.values
        _tick_text = [str(k) for k in _month_starts.index]
        fig.update_xaxes(
            tickvals=_tick_vals, ticktext=_tick_text,
            showgrid=False, zeroline=False,
            tickfont=dict(size=10),
        )
        fig.update_yaxes(
            tickvals=list(range(7)), ticktext=_dow_labels,
            showgrid=False, zeroline=False,
            tickfont=dict(size=10),
            autorange="reversed",
        )
        fig.update_layout(
            title="Occupancy Density Calendar — 365-Day View",
            height=200,
            margin=dict(l=4, r=4, t=40, b=8),
        )
        return style_fig(fig, height=200)
    except Exception:
        return None


def evt_type_class(event_type: str) -> tuple[str, str]:
    """Return (card_class, pill_class) for a given event type string."""
    t = (event_type or "").lower()
    if any(x in t for x in ["festival","music","concert","ohana","doheny"]):
        return "evt-card evt-festival", "evt-type-pill evt-type-festival", "🎵"
    if any(x in t for x in ["surf","wave","beach","paddl"]):
        return "evt-card evt-surf", "evt-type-pill evt-type-surf", "🏄"
    if any(x in t for x in ["tall ships","maritime","sail","harbor","whale","ocean"]):
        return "evt-card evt-maritime", "evt-type-pill evt-type-maritime", "⚓"
    if any(x in t for x in ["holiday","4th","fourth","christmas","firework","parade"]):
        return "evt-card evt-holiday", "evt-type-pill evt-type-holiday", "🎆"
    if any(x in t for x in ["race","run","triathlon","marathon","cycling"]):
        return "evt-card evt-race", "evt-type-pill evt-type-race", "🏁"
    return "evt-card evt-default", "evt-type-pill evt-type-default", "📅"


def tab_summary(text: str) -> str:
    """Returns HTML for a tab-level summary card."""
    return f'<div class="tab-summary">{text}</div>'


