def _h_delta_html(v, fmt="pct"):
    if v == 0: return ""
    cls = "hero-stat-pos" if v >= 0 else "hero-stat-neg"
    arrow = "▲" if v >= 0 else "▼"
    val_str = f"{v:+.1f}%" if fmt == "pct" else f"{v:+.1f}pp"
    return f'<span class="hero-stat-delta {cls}">{arrow} {val_str}</span>'

