            _comp_cmp   = min(20, max(0, _cq_s * 2.0))
            _pulse_score = int(round(_comp_occ + _comp_rvp + _comp_cmp))
            _pulse_score = max(0, min(100, _pulse_score))

            if _pulse_score >= 90:
                _p_color  = "#7C3AED"
                _p_status = "HISTORIC"
            elif _pulse_score >= 75:
                _p_color  = "#21C55D"
